int checks=0;
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);++checks;}
void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QTest::qWait(20);}
void valid(const Document& d){validate(d);check(decode(encode(d))==d,"Independent full caller native-valid BEFORE Window");}
void same(const Session& a,const Session& b){check(a.document()==b.document()&&encode(a.document())==encode(b.document())&&a.preview_document()==b.preview_document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation(),"Entire caller Session/native/History/preview/revision/generation unchanged");}
void write(const QString& path,const Document& d){QFile f(path);const auto b=encode(d);check(f.open(QIODevice::WriteOnly|QIODevice::NewOnly)&&f.write(b.data(),b.size())==static_cast<qint64>(b.size()),"Immutable actual or independent native retained once");}
QByteArray read(const QString& path){QFile f(path);check(f.open(QIODevice::ReadOnly),"Owned native bytes readable");return f.readAll();}
template<class T>T* control(Window& w,const QString& name){for(auto* c:w.findChildren<T*>(name))if(c->isVisible())return c;throw std::runtime_error("Original visible source producer missing");}
void reveal(QWidget* c){QPointer<QWidget> alive=c;for(auto* p=c->parentWidget();p;p=p->parentWidget())if(auto* s=qobject_cast<QScrollArea*>(p))s->ensureWidgetVisible(c);events();check(alive&&alive->isVisible()&&alive->isEnabled(),"Original source producer survives reveal and is enabled");}

const Id expected_id="00000000-0000-4000-8000-000000000001";
Document normalized(Document d,const Id& generated){if(generated.empty())return d;check(d.objects.size()==4&&d.objects.contains(generated)&&d.objects.at(generated).kind==Kind::group&&d.objects.at(generated).children==std::vector<Id>{"shape","peer"},"Exact sole new Folder and retained child IDs");auto node=d.objects.extract(generated);node.key()=expected_id;node.mapped().id=expected_id;d.objects.insert(std::move(node));int count=0;for(auto& id:d.compositions.front().roots)if(id==generated){id=expected_id;++count;}check(count==1,"Only exact new Folder key/id/root occurrence mapped");return d;}
void same_result(const Session& a,const Session& b,const Id& generated){check(normalized(a.document(),generated)==b.document()&&encode(normalized(a.document(),generated))==encode(b.document())&&normalized(a.preview_document(),generated)==b.preview_document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation(),"Entire structural caller Session/native/preview/History/counters with sole new Folder ID mapping");}
Document fixture(){auto d=empty_document("structural-modal-document","comp","art");auto& board=d.compositions.front().artboards.front();board.width=640;board.height=480;for(const auto& id:{Id{"shape"},Id{"peer"},Id{"other"}}){Object object;object.id=id;object.name=id=="shape"?"Zulu":id=="peer"?"Alpha":"Original retained";object.source=default_primitive(id+"-source","nect.shape.rectangle");object.source->parameters.at("width").literal=80;object.source->parameters.at("height").literal=60;object.source->parameters.at("center_x").literal=id=="shape"?320:id=="peer"?180:460;object.source->parameters.at("center_y").literal=240;auto fill=default_operation(id+"-fill","nect.paint.fill");fill.parameters.at("r").literal=id=="shape"?1:0;fill.parameters.at("g").literal=id=="other"?1:0;fill.parameters.at("b").literal=id=="peer"?1:0;object.stack={fill};d.objects.emplace(id,object);d.compositions.front().roots.push_back(id);}d.collections={{"collection","Retained non-owning",{"shape","other"}}};return d;}
void flow(const QString& root,int mode){const bool sort=mode==5||mode==6,folder=mode==7||mode==8,success=mode==4||mode==6||mode==8,foreign_case=mode==0||mode==5||mode==7;auto initial=fixture();valid(initial);auto current=initial;current.objects.at("other").name="Current retained";valid(current);Session base(initial);base.apply({Rename{"other","Current retained"}},0);check(base.document()==current&&base.revision()==1,"Whole independently authored objects/names/order/source/native/History before Window");auto foreign_initial=initial;foreign_initial.id="foreign-structural-document";foreign_initial.objects.at("shape").source->parameters.at("height").literal=90;foreign_initial.objects.at("shape").name="Foreign Zulu";foreign_initial.compositions.front().roots={"other","shape","peer"};valid(foreign_initial);auto foreign_current=foreign_initial;foreign_current.objects.at("other").name="Current retained";valid(foreign_current);Session foreign(foreign_initial);foreign.apply({Rename{"other","Current retained"}},0);check(foreign.document()==foreign_current&&foreign.revision()==base.revision()&&foreign.gesture_generation()==base.gesture_generation(),"Whole foreign source/names/order with equal IDs/counters before Window");auto concurrent=base;concurrent.apply({Rename{"other","Concurrent retained"}},1);auto concurrent_doc=current;concurrent_doc.objects.at("other").name="Concurrent retained";valid(concurrent_doc);check(concurrent.document()==concurrent_doc,"Entire concurrent caller before Window");auto busy=base;busy.begin_gesture(1);busy.update_gesture({Set{{"shape","","generator.height"},90}});auto preview=current;preview.objects.at("shape").source->parameters.at("height").literal=90;valid(preview);check(busy.document()==current&&busy.preview_document()==preview,"Entire active caller preview before Window");auto transformed=current;if(sort)transformed.compositions.front().roots={"peer","shape","other"};else if(folder){Object group;group.id=expected_id;group.name="Created Folder";group.kind=Kind::group;group.children={"shape","peer"};group.anchor[0].literal=250;group.anchor[1].literal=240;transformed.objects.emplace(group.id,group);transformed.compositions.front().roots={expected_id,"other"};}else{transformed.objects.at("shape").name="Component 1";transformed.objects.at("peer").name="Component 2";}valid(transformed);auto committed=base;if(sort)committed.apply({ReorderObjects{"comp","",{"peer","shape","other"}}},1);else if(folder)committed.apply({GroupContiguous{"comp","",{"shape","peer"},expected_id,"Created Folder"}},1);else committed.apply({Rename{"shape","Component 1"},Rename{"peer","Component 2"}},1);check(committed.document()==transformed,"Full independent names/paint order/Folder with literal centered Anchor matches typed commands before Window");auto history=committed;history.undo(2);check(history.document()==current,"Full structural Undo before Window");history.redo(3);check(history.document()==transformed&&history.history()==committed.history(),"One structural History/full Redo before Window");auto expected=base;if(foreign_case)expected=foreign;else if(mode==2)expected=concurrent;else if(mode==3)expected=busy;else if(success)expected=committed;const auto prefix=root+"/mode-"+QString::number(mode);write(prefix+"-expected.nect",expected.document());write(prefix+"-expected-preview.nect",expected.preview_document());
QSettings settings(prefix+"-settings.ini",QSettings::IniFormat);settings.setFallbacksEnabled(false);Window w(prefix+"-recovery",std::make_unique<FolderLibrary>(settings,FolderLibrary::PersistOverride{},FolderLibrary::ReadbackOverride{},prefix+"-assets"),&settings);w.host.session=base;w.host.edited();w.resize(1400,1050);w.show();events();w.canvas->set_active_artboard("comp","art",false);w.canvas->set_selections({{"shape",""},{"peer",""}});events();auto* actor=w.findChild<QAction*>(sort?"sort-selected-name-paint-order":folder?"create-folder-from-selection":"batch-rename-selection");check(actor&&actor->isEnabled(),"Original structural preview action enabled");const auto original_host=w.host.session_id;QString callback_error;int stages=0;QTimer::singleShot(0,&w,[&]{try{auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget());check(dialog&&dialog->objectName()==(sort?"sort-paint-order-dialog":folder?"create-folder-from-selection-dialog":"batch-rename-dialog"),"Original exact structural preview modal");++stages;if(sort){check(dialog->findChild<QLabel*>("sort-paint-order-before-id-0")->text()=="shape"&&dialog->findChild<QLabel*>("sort-paint-order-after-id-0")->text()=="peer","Original independent full order preview exact IDs");}else if(folder){auto* name=dialog->findChild<QLineEdit*>("create-folder-from-selection-name");check(name&&name->text()=="Folder","Original Folder name producer");name->setText("Created Folder");check(dialog->findChild<QPlainTextEdit*>("create-folder-from-selection-preview")->toPlainText().contains("Flattened paint order: unchanged"),"Original source hierarchy preview");}else{check(dialog->findChild<QLabel*>("batch-rename-id-0")->text()=="shape"&&dialog->findChild<QLabel*>("batch-rename-id-1")->text()=="peer","Original ordered stable target IDs");auto* name=dialog->findChild<QLineEdit*>("batch-rename-base");check(name&&name->text()=="Zulu","Original source name before draft");name->setText("Component");}if(foreign_case)w.host.session=foreign;else if(mode==1)w.host.session_id+="-changed";else if(mode==2)w.host.session=concurrent;else if(mode==3)w.host.session=busy;check(dialog->grab().save(prefix+"-dialog.png"),"Actual original structural preview before Apply");auto* buttons=dialog->findChild<QDialogButtonBox*>();check(buttons&&buttons->button(QDialogButtonBox::Ok),"Original modal Apply button");buttons->button(QDialogButtonBox::Ok)->click();}catch(const std::exception& e){callback_error=QString::fromUtf8(e.what());if(auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget()))dialog->reject();}});actor->trigger();events();check(callback_error.isEmpty()&&stages==1,"Original structural Apply completes without fixture exception");const auto observed=w.host.session;const auto status=w.statusBar()->currentMessage();Id generated;if(mode==8){check(observed.document().objects.size()==4,"Exactly one new Folder");for(const auto& [id,object]:observed.document().objects)if(!current.objects.contains(id))generated=id;check(generated.size()==36&&generated!=expected_id,"Actual new Folder UUID independent of fixed expected ID");}write(prefix+"-observed.nect",observed.document());write(prefix+"-observed-preview.nect",observed.preview_document());const auto actual=normalized(observed.document(),generated),actual_preview=normalized(observed.preview_document(),generated);write(prefix+"-normalized.nect",actual);write(prefix+"-normalized-preview.nect",actual_preview);check(w.grab().save(prefix+"-window.png"),"Actual whole structural result before Save");QJsonObject v{{"mode",mode},{"status",status},{"generated_id",QString::fromStdString(generated)},{"document_equal",actual==expected.document()},{"preview_equal",actual_preview==expected.preview_document()},{"history_equal",observed.history()==expected.history()},{"revision",qint64(observed.revision())},{"gesture_active",observed.gesture_active()},{"gesture_generation",qint64(observed.gesture_generation())},{"caller_identity_preserved",mode!=3||observed.gesture_identity()==busy.gesture_identity()},{"host_equal",mode==1?w.host.session_id!=original_host:w.host.session_id==original_host},{"view_equal",w.canvas->selected_objects()==(mode==8?std::vector<Id>{generated}:std::vector<Id>{"shape","peer"})&&w.canvas->active_composition()=="comp"&&w.canvas->active_artboard()=="art"},{"save_intent",mode!=3}};QFile metadata(prefix+"-producer.json");check(metadata.open(QIODevice::WriteOnly|QIODevice::NewOnly),"Immutable whole structural caller readback before Save");metadata.write(QJsonDocument(v).toJson());metadata.close();same_result(observed,expected,generated);check(v["view_equal"].toBool()&&v["host_equal"].toBool()&&v["caller_identity_preserved"].toBool(),"Caller view and gesture identity preserved, only current new Folder selected");if(mode==0||mode==1||mode==5||mode==7)check(status.startsWith("SESSION_CONFLICT:"),"Structural foreign Doc/Host refusal explicit");if(mode==2)check(status.startsWith("REVISION_CONFLICT:"),"Structural revision refusal explicit");if(mode==3)check(status.startsWith("GESTURE_ACTIVE:"),"Structural active caller refusal explicit");if(success){w.host.session.undo(2);check(w.host.session.document()==current,"Actual whole structural Undo");w.host.session.redo(3);check(normalized(w.host.session.document(),generated)==transformed,"Actual whole structural Redo");w.host.session=observed;}if(mode!=3){w.host.save(prefix+"-saved.nect");w.host.flush();events();same_result(w.host.session,expected,generated);check(read(prefix+"-saved.nect")==read(prefix+"-observed.nect")&&normalized(decode(read(prefix+"-saved.nect").toStdString()),generated)==expected.document()&&QFile::copy(prefix+"-saved.nect",prefix+"-snapshot.nect"),"Whole raw structural Save/snapshot; sole new Folder ID mapping");}w.close();events();}
